export const getListFinancesUrl = (params?: ListFinancesParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/finances?${stringifiedParams}` : `/api/finances`
}

/**
 * @summary List all finance entries
 */
export const listFinances = async (params?: ListFinancesParams, options?: RequestInit): Promise<Finance[]> => {

  return customFetch<Finance[]>(getListFinancesUrl(params),
  {
    ...options,
    method: 'GET'


  }
);}





export const getListFinancesQueryKey = (params?: ListFinancesParams,) => {
    return [
    `/api/finances`, ...(params ? [params] : [])
    ] as const;
    }


